def size(node):
    if node is None:
        return 0
    return 1 + size(node.left) + size(node.right)

memo = {}
def fib(n):
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib(n - 1) + fib(n - 2)
    return memo[n]

